describe('Clipboard - fix verification', () => {
  describe('with unsupported formats', () => {
    test('code-block format registered: <pre> produces code-block', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([CodeBlock]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<pre> 01 \n 23 </pre>' });
      expect(delta.ops[0].insert).toBe(' 01 \n 23 \n');
      expect(delta.ops[0].attributes?.['code-block']).toBe(true);
    });

    test('code-block NOT registered: <pre> produces plain text', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<pre> 01 \n 23 </pre>' });
      expect(delta.ops[0].insert).toBe(' 01 \n 23 ');
      expect(delta.ops[0].attributes?.['code-block']).toBeUndefined();
    });

