      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([DirectionStyle]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<p style="direction:rtl;">Test</p>' });
      expect(delta.ops[0].insert).toBe('Test\n');
      expect(delta.ops[0].attributes?.direction).toBe('rtl');
    });

    test('direction NOT registered: <p style="direction:rtl;"> plain text', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<p style="direction:rtl;">Test</p>' });
      expect(delta.ops[0].insert).toBe('Test');
      expect(delta.ops[0].attributes?.direction).toBeUndefined();
    });

    test('color registered: nested spans produce correct color', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([ColorStyle]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<span style="color: red;"><span style="color: blue;">Test</span></span>' });
      expect(delta.ops[0].insert).toBe('Test');
      expect(delta.ops[0].attributes?.color).toBe('blue');
    });

    test('color NOT registered: nested spans produce plain text', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<span style="color: red;"><span style="color: blue;">Test</span></span>' });
      expect(delta.ops[0].insert).toBe('Test');
      expect(delta.ops[0].attributes?.color).toBeUndefined();
    });

    test('bold NOT registered: <b> produces plain text', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<b>Bold</b>' });
      expect(delta.ops[0].insert).toBe('Bold');
      expect(delta.ops[0].attributes?.bold).toBeUndefined();
    });

    test('bold registered: <b> produces bold', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([Bold]);
