      expect(delta.ops[0].insert).toBe('Italic');
      expect(delta.ops[0].attributes?.italic).toBeUndefined();
    });

    test('strike NOT registered: <strike> produces plain text', () => {
      const container = document.body.appendChild(document.createElement('div'));
      const registry = createRegistry([]);
      const quill = new Quill(container, { registry });
      const delta = quill.clipboard.convert({ html: '<strike>Deleted</strike>' });
      expect(delta.ops[0].insert).toBe('Deleted');
      expect(delta.ops[0].attributes?.strike).toBeUndefined();
    });
  });
});
