function matchStyles(
  node: HTMLElement,
  delta: Delta,
  scroll: ScrollBlot,
) {
  const formats: Record<string, unknown> = {};
  const style: Partial<CSSStyleDeclaration> = node.style || {};
  if (style.fontStyle === 'italic' && scroll.query('italic', Scope.BLOT) != null) {
    formats.italic = true;
  }
  if (
    style.textDecoration === 'underline' &&
    scroll.query('underline', Scope.BLOT) != null
  ) {
    formats.underline = true;
  }
  if (
    style.textDecoration === 'line-through' &&
    scroll.query('strike', Scope.BLOT) != null
  ) {
    formats.strike = true;
  }
  if (
    (style.fontWeight?.startsWith('bold') ||
      // @ts-expect-error Fix me later
      parseInt(style.fontWeight, 10) >= 700) &&
    scroll.query('bold', Scope.BLOT) != null
  ) {
    formats.bold = true;
  }
  if (Object.keys(formats).length > 0) {
    delta = applyFormat(delta, formats);
  }
  // @ts-expect-error
  if (parseFloat(style.textIndent || 0) > 0) {
    // Could be 0.5in
    return new Delta().insert('\t').concat(delta);
  }
  return delta;
}

